def dif_Square(n: int) -> bool:
    # We want to check if n can be written as a² - b² = (a-b)(a+b) = n
    # Let x = a-b, y = a+b, then n = x * y
    # a = (x + y)/2, b = (y - x)/2 must be integers => x and y must have the same parity (both even or both odd)
    # So we need to find factors x, y of n with same parity

    # Handle n=0 separately: 0 = 0² - 0², so True
    if n == 0:
        return True

    abs_n = abs(n)
    # Iterate over factors of abs(n)
    # For each factor x, y = n // x (with sign)
    # Check parity and if a,b are integers

    # Factors can be negative, but since a,b integers, sign handled by x,y

    # To avoid float division, check (x+y) and (y - x) evenness

    for x in range(1, int(abs_n**0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x

            # Check both (x,y) and (-x, -y) pairs with sign to get n
            for (X, Y) in [(x, y), (-x, -y)]:
                if X * Y == n:
                    # Check parity
                    if (X + Y) % 2 == 0 and (Y - X) % 2 == 0:
                        return True

            # Also check (y, x) and (-y, -x) pairs to cover all factor pairs
            for (X, Y) in [(y, x), (-y, -x)]:
                if X * Y == n:
                    if (X + Y) % 2 == 0 and (Y - X) % 2 == 0:
                        return True

    return False

