def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome is 1 followed by zeros and ending with 1, length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    # Function to create palindrome by mirroring left half to right
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    mid = length // 2

    if odd_length:
        left = s[:mid+1]
    else:
        left = s[:mid]

    # Construct palindrome from left
    pal = int(make_palindrome(left, odd_length))

    if pal > num:
        return pal

    # Increment the left part and mirror again
    # Convert left to int, increment, then back to string with zero padding if needed
    left_num = int(left) + 1
    left_str = str(left_num)

    # If length changed after increment (e.g. 99 -> 100), need to adjust
    if len(left_str) > len(left):
        # For example, from 999 to 1000, palindrome length increases by 1 or 2 digits
        # Just return 10...01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    pal = int(make_palindrome(left_str, odd_length))
