def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[i][x]: number of sequences of length i starting with x
    # For i=1, dp[1][x] = 1 for all x in 1..m
    # For i>1, dp[i][x] = sum of dp[i-1][y] for all y >= 2*x and y <= m

    if n == 1:
        return m  # sequences of length 1: each starting element counts as 1 sequence

    dp_prev = [1] * (m + 1)  # dp for sequences of length 1 (index 1..m)
    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        # To efficiently compute sums over ranges, use prefix sums of dp_prev
        prefix_sum = [0] * (m + 2)
        for i in range(1, m + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp_prev[i]

        for x in range(1, m + 1):
            start = 2 * x
            if start > m:
                dp_curr[x] = 0
            else:
                dp_curr[x] = prefix_sum[m] - prefix_sum[start - 1]
        dp_prev = dp_curr

    return sum(dp_prev[1:])

