            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left = s[:half_len]
    odd_len = (length % 2 != 0)

    # Candidate palindrome by mirroring left half
    pal_candidate = make_palindrome(left, odd_len)

    # If candidate palindrome is >= num, we need to decrement left half and then mirror again
    if pal_candidate >= num:
